package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.util.*;import java.text.*;
/** Real SDK map view, timetable boundaries and lifecycle; offline tile fixtures do not prove live navigation. */
public class DriveDashboardChecks extends Instrumentation {
 LauncherActivity a;int n;android.content.SharedPreferences prefs;Map<String,?> saved;
 void check(boolean v,String why){if(!v)throw new AssertionError(why);n++;}
 void ui(Runnable r){Throwable[] t={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){t[0]=e;}});waitForIdleSync();if(t[0]!=null)throw new AssertionError(t[0]);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int result=Activity.RESULT_CANCELED;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(prefs.getAll());prefs.edit().putInt("dashboard_panel",0).putString("jakim_zone","SGR02").putBoolean("dashboard_location",false).apply();
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(1);a.worker.execute(()->a.main.post(ready::countDown));check(ready.await(45,java.util.concurrent.TimeUnit.SECONDS),"catalog ready");waitForIdleSync();
  ui(()->{a.page="drive";a.render();check(a.driveDashboard!=null,"Drive opens native dashboard");DriveDashboard d=a.driveDashboard;check(d.map!=null,"real native map SDK available on API27");d.map.setUseDataConnection(false);check(!d.listening,"no location tracking before opt-in");check(d.map.getOverlays().size()==1,"no invented device position marker");check(d.media.active,"media callback subscription active");a.setJakimZone("SGR02");});
  java.util.concurrent.CountDownLatch network=new java.util.concurrent.CountDownLatch(1);a.networkWorker.execute(()->a.main.post(network::countDown));check(network.await(45,java.util.concurrent.TimeUnit.SECONDS),"timetable ready");waitForIdleSync();
  ui(()->{DriveDashboard d=a.driveDashboard;check(a.jakimDays.containsKey("2026-11-03"),"real timetable loaded");String time=a.jakimDays.get("2026-11-03").times[0];try{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);f.setTimeZone(JakimCalendar.MY);long at=f.parse("2026-11-03 "+time).getTime();d.tick(at-60000);check(d.prayer.getText().toString().contains("Subuh")&&d.prayer.getText().toString().contains("1m lagi"),"live one-minute countdown uses official time");d.tick(at-120000);check(d.prayer.getText().toString().contains("2m lagi"),"minute update without rebuilding root");d.tick(f.parse("2027-11-03 12:00").getTime());check(d.prayer.getText().toString().contains("belum tersedia"),"expired timetable not invented");}catch(java.text.ParseException e){throw new AssertionError(e);}
   for(int[] size:new int[][]{{1024,600},{800,480}}){d.measure(View.MeasureSpec.makeMeasureSpec(size[0],View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size[1],View.MeasureSpec.EXACTLY));d.layout(0,0,size[0],size[1]);check(d.map.getWidth()>size[0]/2,"large map region");check(d.map.getHeight()>200,"map has useful height");}
   d.pause();check(!d.active&&!d.listening&&!d.media.active,"background stops media/location");d.resume();check(d.active&&d.media.active,"resume restores callback subscriptions");d.tick(System.currentTimeMillis());
   d.setMode(3);check(d.map==null&&d.web!=null,"YouTube mode releases native map");DashWebPlayer oldWeb=d.web;d.setMode(2);check(d.web==null&&d.fm!=null&&oldWeb.web==null,"FM mode releases browser");DashFmPanel oldFm=d.fm;d.setMode(1);check(d.fm==null&&!oldFm.controller.owned&&d.largeMedia!=null&&d.largeMedia.active,"audio mode releases radio and binds media");d.setMode(0);d.map.setUseDataConnection(false);check(d.largeMedia==null&&d.map!=null,"return to map releases audio bridge");check(d.prayer.getParent()!=null,"live prayer widget remains across modes");
  });
  try{getTargetContext().getPackageManager().getServiceInfo(new ComponentName(getTargetContext(),"com.shazwan.idash3.SplitService"),0);throw new AssertionError("split service still exposed");}catch(android.content.pm.PackageManager.NameNotFoundException expected){n++;}
  android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();if(shot!=null){try(java.io.OutputStream file=new java.io.FileOutputStream(new java.io.File(a.getFilesDir(),"drive-dashboard.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,file);}shot.recycle();}
  ui(()->{DriveDashboard old=a.driveDashboard;a.page="home";a.render();check(old.closed&&old.map==null&&!old.listening,"leaving dashboard releases map and GPS");});
  out.putString("stream","PASS: "+n+" Drive Dashboard assertions\n");result=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+n+": "+t+"\n");}finally{if(a!=null)ui(a::finish);if(prefs!=null&&saved!=null)AppearanceChecks.restore(prefs,saved);}finish(result,out);}
}
